body=r'''<!doctype html><html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>伊瑟兰 · 成就图鉴原型</title>
<style>
:root{color-scheme:dark;--bg:#0d1421;--surface:#182334;--surface2:#223146;--border:#6f5940;--text:#f3eee4;--muted:#acb7c7;--gold:#c4a16b;--focus:#eacb8b;--radius:14px;}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 20% 0,#25344c 0,#101927 38%,#0d1421 80%);color:var(--text);font-family:system-ui,-apple-system,'Noto Sans CJK SC','Microsoft YaHei',sans-serif;min-height:100vh}button,input,select{font:inherit}button{cursor:pointer}button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid var(--focus);outline-offset:2px}button:disabled{opacity:.5;cursor:not-allowed}.shell{max-width:1230px;margin:auto;padding:22px 18px}.top{display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap;margin-bottom:14px}.brand small{display:block;color:var(--gold);letter-spacing:.1em}.brand h1{margin:4px 0;font-size:clamp(24px,3vw,36px);font-weight:650}.badge{border:1px solid #876b49;background:#251f1c;border-radius:100px;padding:6px 12px;color:#dfc18a;font-size:12px}.muted{color:var(--muted)}.toolrow{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.btn{border:1px solid #6f624c;background:#2b3547;color:var(--text);border-radius:10px;padding:9px 14px;min-height:44px}.btn.primary{background:linear-gradient(110deg,#977448,#c8a573);color:#141923;border:0;font-weight:700}.btn.ghost{background:transparent}.dashboard{border:1px solid #65563c;border-radius:16px;background:linear-gradient(140deg,#1e293b,#151d2c);padding:17px 20px;margin-bottom:16px;display:grid;grid-template-columns:1fr 270px;gap:14px;align-items:center}.dashlabel{font-size:13px;color:#c9b28b}.progress-title{font-size:23px;font-weight:650;margin:4px 0}.progress-rail{height:10px;border-radius:99px;overflow:hidden;background:#3b4656;margin-top:10px}.progress-fill{background:linear-gradient(90deg,#98734c,#e3c48a);height:100%;width:20%;transition:width .25s}.tabs{display:flex;gap:8px;flex-wrap:wrap}.tabs button.active{background:#b08d5b;color:#141923;font-weight:700}.workspace{display:grid;grid-template-columns:175px minmax(0,1fr);min-height:620px;max-height:calc(100vh - 205px);border:1px solid #465163;border-radius:16px;overflow:hidden;background:#121e2e}.side{padding:14px;border-right:1px solid #3e4958;background:#172235}.side .cat{display:block;width:100%;text-align:left;margin:5px 0;padding:10px;border-radius:10px;border:1px solid transparent;background:transparent;color:#d4dded;min-height:43px}.side .cat.active{border-color:#977d53;background:#303247;color:#ffe8b8}.content{min-width:0;display:flex;flex-direction:column;padding:14px 16px}.filters{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:12px}.filters input,.filters select{background:#1e2b3f;border:1px solid #59677a;border-radius:8px;color:#f7f3ee;padding:9px;min-height:42px}.filters input{flex:1;min-width:140px}.grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px;align-content:start;flex:1;overflow-y:auto;min-height:0;padding-bottom:6px}.achievement{position:relative;text-align:center;min-height:175px;background:linear-gradient(145deg,#263247,#1c2636);border:1px solid #526074;border-radius:13px;padding:11px 6px;display:flex;flex-direction:column;align-items:center;gap:5px;color:#fff}.achievement.unearned{filter:saturate(.7)}.achievement img{width:79px;height:79px;object-fit:contain}.achievement .name{font-size:13px;font-weight:620;line-height:1.4;overflow:hidden;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2}.achievement .tag{font-size:11px;color:#cad1dc}.achievement .status{font-size:10px;position:absolute;top:8px;right:7px;color:#d8c499;border:1px solid #7b704e;padding:1px 5px;border-radius:100px;background:#2f3340}.achievement.unearned .status{color:#c8cbd0;border-color:#536071}.foot{display:flex;align-items:center;justify-content:space-between;gap:8px;padding-top:11px}.foot small{color:var(--muted)}.ending{display:none}.ending.show{display:block}.summary-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:15px 0}.metric{border:1px solid #586176;border-radius:13px;background:#1b293d;padding:17px}.metric strong{display:block;font-size:clamp(23px,3vw,36px);color:#edd7aa;margin-top:8px}.metric small{color:#b7c0ce}.results{display:grid;grid-template-columns:1fr 1fr;gap:14px}.panel{padding:17px;background:#182538;border:1px solid #4c5a6d;border-radius:14px}.panel h2{margin:0 0 12px;font-size:18px}.pills{display:flex;gap:8px;flex-wrap:wrap}.pill{display:flex;align-items:center;gap:7px;border:1px solid #4e5a6e;background:#242f43;border-radius:10px;padding:7px 9px;font-size:12px}.pill img{width:36px;height:36px}.categories{display:grid;gap:10px}.catprogress{display:flex;gap:8px;align-items:center;justify-content:space-between}.catprogress span{color:#d7dce2;font-size:13px}.dialog-overlay{display:none;position:fixed;inset:0;background:#05070bd9;align-items:center;justify-content:center;padding:14px;z-index:100}.dialog-overlay.show{display:flex}.dialog{width:min(520px,95vw);max-height:90dvh;overflow:auto;border:1px solid #a27c46;border-radius:16px;background:linear-gradient(160deg,#293448,#111a2b);padding:22px;box-shadow:0 20px 80px #0009}.dialog-head{display:flex;justify-content:space-between;align-items:center}.dialog-body{text-align:center}.dialog-body img{width:116px;height:116px}.dialog-body h2{margin:8px 0 5px}.dialog-body p{line-height:1.8}.dialog-meta{color:#aebccb;font-size:13px}.toast{position:fixed;z-index:70;top:calc(18px + env(safe-area-inset-top));right:16px;width:min(350px,calc(100vw - 32px));border:1px solid #d5b374;border-radius:14px;background:linear-gradient(135deg,#323048,#142337);box-shadow:0 12px 45px #0008;padding:12px;display:none}.toast.show{display:block}.toast-grid{display:flex;gap:11px;align-items:center}.toast img{width:56px;height:56px}.toast strong{display:block;margin-top:3px}.caption{font-size:12px;color:#b3bfd0;line-height:1.5}.sr-only{position:absolute;clip-path:inset(50%);height:1px;width:1px;overflow:hidden;white-space:nowrap}.empty{color:#bfc5cf;padding:22px;text-align:center;grid-column:1/-1}.smallnote{font-size:12px;color:#aab6c3;line-height:1.6;margin-top:7px}
@media(max-width:990px){.grid{grid-template-columns:repeat(3,minmax(0,1fr))}.workspace{max-height:none;min-height:610px}.dashboard{grid-template-columns:1fr}.results{grid-template-columns:1fr}}
@media(max-width:650px){.shell{padding:10px;height:100dvh;display:flex;flex-direction:column;overflow:hidden}.top{flex:0 0 auto}.dashboard{flex:0 0 auto}.workspace{display:flex;flex:1 1 auto;flex-direction:column;max-height:none;min-height:0;overflow:hidden}.side{flex:0 0 auto;display:flex;gap:7px;overflow-x:auto;border-right:0;border-bottom:1px solid #3e4958;padding:7px}.side .cat{white-space:nowrap;flex:0 0 auto;width:auto;min-width:100px;margin:3px;padding:10px 12px}.content{flex:1;min-height:0;padding:11px;display:flex;flex-direction:column}.grid{grid-template-columns:repeat(2,minmax(0,1fr));max-height:none;min-height:0;flex:1;overflow-y:auto}.achievement{min-height:167px}.dashboard{padding:12px}.summary-grid{grid-template-columns:1fr 1fr}.metric:last-child{grid-column:span 2}.top{margin-bottom:8px}.foot{padding-top:8px;flex:0 0 auto}.filters{flex:0 0 auto;margin-bottom:8px;gap:6px}.filters input,.filters select{min-height:38px;padding:7px}.ending.show{flex:1;min-height:0;overflow-y:auto}}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{transition:none!important;animation:none!important}}
</style></head><body><div class="shell"><header class="top"><div class="brand"><small>伊瑟兰 · 冒险者档案</small><h1>成就图鉴</h1></div><div class="toolrow"><span class="badge">设计原型 · 模拟数据 · 未接游戏后端</span><button class="btn" id="demoUnlock">模拟解锁下一项</button><button class="btn primary" id="switchView">查看结局总结</button></div></header>
<section class="dashboard"><div><div class="dashlabel">冒险者生涯</div><div class="progress-title" id="totalProgress">已解锁 0 / 50</div><div class="progress-rail" aria-label="成就总进度"><div class="progress-fill" id="totalFill"></div></div></div><div class="muted" id="substats">记录那些被世界记住的事情。隐藏事迹将在亲历后显现。</div></section>
<section class="workspace" id="gallery"><nav class="side" id="categoryNav" aria-label="成就分类"></nav><div class="content"><div class="filters"><input id="search" aria-label="搜索可公开成就" placeholder="搜索已公开成就…"><select id="statusFilter" aria-label="解锁筛选"><option value="all">全部状态</option><option value="earned">已获得</option><option value="unearned">未获得</option></select><select id="rarityFilter" aria-label="稀有度筛选"><option value="all">全部稀有度</option><option value="common">普通</option><option value="rare">稀有</option><option value="epic">史诗</option><option value="legendary">传奇</option></select><select id="sort" aria-label="排序"><option value="default">默认排序</option><option value="recent">最近获得</option><option value="rarity">稀有度</option></select></div><div class="grid" id="achievementGrid" role="list"></div><div class="foot"><small id="pageText">第 1 页</small><div class="toolrow"><button class="btn" id="prev">上一页</button><button class="btn" id="next">下一页</button></div></div></div></section>
<section class="ending" id="ending"><div class="panel"><h2>本局终章 · 第七声之后</h2><p class="muted">世界的走向由已确认的事实决定；本局玩家的事业、关系与传奇则进入冒险者编年史。以下为模拟界面。</p></div><div class="summary-grid"><div class="metric"><small>本局新获得</small><strong id="newInRun">0</strong></div><div class="metric"><small>本局已达成（示例）</small><strong id="achievedInRun">0</strong></div><div class="metric"><small>账号永久进度</small><strong id="accountTotal">0 / 50</strong></div></div><div class="results"><div class="panel"><h2>本局新成就</h2><div id="runBadges" class="pills"></div><p class="smallnote">无论成就数量多少，结局都要优先总结玩家真正做过的选择。</p></div><div class="panel"><h2>分类收藏进度</h2><div id="catProgress" class="categories"></div><p class="smallnote">隐藏成就统计入分母，但不能泄露未解锁的名称、条件和图标。</p></div></div><div class="panel" style="margin-top:14px"><h2>冒险者编年史 · 示例</h2><p>第 12 轮：玩家援助低潮街的居民。<br>第 29 轮：玩家创立独立救助组织。<br>第 57 轮：组织难民撤离，改变了城市的命运。</p><p class="smallnote">这是占位示例，实际内容应严格引用本局已提交的事件日志，不得编造。</p><button class="btn" id="returnGallery">返回图鉴</button></div></section>
</div><div class="dialog-overlay" id="overlay"><div class="dialog" role="dialog" aria-modal="true" aria-labelledby="detailTitle"><div class="dialog-head"><span class="badge">冒险者成就</span><button class="btn ghost" id="closeDialog" aria-label="关闭详情">关闭 ✕</button></div><div class="dialog-body" id="detailBody"></div></div></div><div class="toast" id="toast" aria-live="polite"></div>
<script>
// OFFLINE MOCK ONLY. In production secret definitions/trigger conditions must NOT be bundled to an unearned client.
const CATALOG=__FULL_JSON__;
const INITIAL_PUBLIC=__PUBLIC_JSON__;
const BASE='../assets/icons/svg/';
const categories=[['all','全部成就','50'],['ST','剧情与世界','12'],['RE','人物与关系','10'],['EX','探索与发现','10'],['SB','沙盒与创造','8'],['LG','隐藏与传奇','10']];
const rarityNames={common:'普通',rare:'稀有',epic:'史诗',legendary:'传奇'};
const rarityRank={common:0,rare:1,epic:2,legendary:3};
let earned=new Set(['ST01','ST02','ST04','ST05','RE01','RE03','EX01','EX03','SB01','SB08']);
let newlyEarned=[];let category='all';let page=0;let view='gallery';let lastFocus=null;
const $=id=>document.getElementById(id);
function exposed(r){if(earned.has(r.id))return r;return INITIAL_PUBLIC.find(x=>x.id===r.id)}
function iconSrc(r){const d=exposed(r);const file=d.icon.split('/').pop();return BASE+file;}
function updateHeader(){const n=earned.size;$('totalProgress').textContent=`已解锁 ${n} / ${CATALOG.length}`;$('totalFill').style.width=(100*n/CATALOG.length)+'%';$('substats').textContent=`${Math.round(100*n/CATALOG.length)}% 完成 · 本次演示新增 ${newlyEarned.length} 项 · 不影响真实账号`;}
function renderNav(){const nav=$('categoryNav');nav.innerHTML='';for(const [id,label,total] of categories){const b=document.createElement('button');b.className='cat'+(category===id?' active':'');b.textContent=`${label} ${total}`;b.setAttribute('aria-pressed',category===id?'true':'false');b.onclick=()=>{category=id;page=0;renderAll()};nav.appendChild(b)}}
function filtered(){const q=$('search').value.trim().toLowerCase();const s=$('statusFilter').value;const rar=$('rarityFilter').value;const arr=CATALOG.filter(r=>(category==='all'||r.category===category)&&(s==='all'||(s==='earned'?earned.has(r.id):!earned.has(r.id)))&&(rar==='all'||rar===r.rarity)&&(!q||[exposed(r).name,exposed(r).description].join(' ').toLowerCase().includes(q)));const sort=$('sort').value;if(sort==='recent')arr.sort((a,b)=>newlyEarned.indexOf(b.id)-newlyEarned.indexOf(a.id));if(sort==='rarity')arr.sort((a,b)=>rarityRank[b.rarity]-rarityRank[a.rarity]);return arr;}
function renderGrid(){const all=filtered();const count=matchMedia('(max-width:650px)').matches?8:15;const pages=Math.max(1,Math.ceil(all.length/count));page=Math.min(page,pages-1);const grid=$('achievementGrid');grid.innerHTML='';for(const r of all.slice(page*count,(page+1)*count)){const d=exposed(r);const unlocked=earned.has(r.id);const b=document.createElement('button');b.className='achievement'+(unlocked?'':' unearned');b.setAttribute('role','listitem');b.innerHTML=`<span class="status">${unlocked?'✓ 已获得':'🔒 未获得'}</span><img alt="" src="${iconSrc(r)}"><span class="name"></span><span class="tag">${r.categoryName} · ${rarityNames[r.rarity]}</span>`;b.querySelector('.name').textContent=d.name;b.onclick=()=>openDetail(r);grid.appendChild(b)}if(!all.length)grid.innerHTML='<div class="empty">没有符合条件的成就。</div>';$('pageText').textContent=`第 ${page+1} / ${pages} 页 · ${all.length} 项`;$('prev').disabled=page===0;$('next').disabled=page>=pages-1;}
function renderEnding(){const n=earned.size;$('newInRun').textContent=newlyEarned.length+' 项';$('achievedInRun').textContent=newlyEarned.length+' 项';$('accountTotal').textContent=n+' / '+CATALOG.length;const rb=$('runBadges');rb.innerHTML='';for(const id of newlyEarned){const r=CATALOG.find(x=>x.id===id);const pill=document.createElement('div');pill.className='pill';pill.innerHTML=`<img src="${iconSrc(r)}" alt=""><span></span>`;pill.querySelector('span').textContent=r.name;rb.appendChild(pill)}if(!newlyEarned.length)rb.textContent='当前演示没有本局新解锁成就。';const el=$('catProgress');el.innerHTML='';for(const [id,label] of categories.slice(1)){const n=CATALOG.filter(x=>x.category===id).length;const k=CATALOG.filter(x=>x.category===id&&earned.has(x.id)).length;const d=document.createElement('div');d.className='catprogress';d.innerHTML=`<span>${label}</span><span>${k} / ${n}</span>`;el.appendChild(d)}}
function renderAll(){updateHeader();renderNav();renderGrid();renderEnding()}
function openDetail(r){const d=exposed(r);const unlocked=earned.has(r.id);lastFocus=document.activeElement;const main=$('detailBody');main.innerHTML='';const img=document.createElement('img');img.src=iconSrc(r);img.alt='成就徽章';main.appendChild(img);const h=document.createElement('h2');h.id='detailTitle';h.textContent=d.name;main.appendChild(h);const p=document.createElement('p');p.textContent=d.description;main.appendChild(p);const meta=document.createElement('p');meta.className='dialog-meta';meta.textContent=`${r.categoryName} · ${rarityNames[r.rarity]} · ${unlocked?'已解锁':'尚未解锁'}`;main.appendChild(meta);if(unlocked){const x=document.createElement('p');x.textContent=r.flavor;main.appendChild(x)}if(!unlocked&&r.visibility==='public'){const x=document.createElement('p');x.className='smallnote';x.textContent='根据已确认的剧情事件推进。当前原型没有连接真实存档进度。';main.appendChild(x)}$('overlay').classList.add('show');$('closeDialog').focus();}
function closeDetail(){$('overlay').classList.remove('show');if(lastFocus&&lastFocus.isConnected)lastFocus.focus()}
let toastTimer=null;function showToast(r){clearTimeout(toastTimer);const node=$('toast');node.innerHTML=`<div class="caption">✦ 成就解锁 · ${rarityNames[r.rarity]}</div><div class="toast-grid"><img src="${iconSrc(r)}" alt=""><div><strong></strong><div class="caption"></div></div></div>`;node.querySelector('strong').textContent=r.name;node.querySelector('.toast-grid .caption').textContent=r.flavor;node.classList.add('show');node.onclick=()=>{node.classList.remove('show');openDetail(r)};toastTimer=setTimeout(()=>node.classList.remove('show'),5500)}
function demoUnlock(){const r=CATALOG.find(x=>!earned.has(x.id));if(!r){alert('演示成就已全部解锁');return}earned.add(r.id);newlyEarned.push(r.id);renderAll();if(!$('overlay').classList.contains('show'))showToast(r)}
function switchView(){view=view==='gallery'?'ending':'gallery';$('gallery').style.display=view==='gallery'?'grid':'none';$('ending').classList.toggle('show',view==='ending');$('switchView').textContent=view==='ending'?'返回成就图鉴':'查看结局总结';renderAll()}
$('demoUnlock').onclick=demoUnlock;$('switchView').onclick=switchView;$('returnGallery').onclick=()=>{if(view==='ending')switchView()};$('prev').onclick=()=>{page--;renderGrid()};$('next').onclick=()=>{page++;renderGrid()};for(const id of ['search','statusFilter','rarityFilter','sort'])$(id).addEventListener(id==='search'?'input':'change',()=>{page=0;renderGrid()});$('closeDialog').onclick=closeDetail;$('overlay').onclick=e=>{if(e.target===$('overlay'))closeDetail()};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('overlay').classList.contains('show'))closeDetail();if(e.key==='Tab'&&$('overlay').classList.contains('show')){$('closeDialog').focus();e.preventDefault()}});window.addEventListener('resize',()=>renderGrid());renderAll();
</script></body></html>'''
body=body.replace('__FULL_JSON__',json.dumps(all_data,ensure_ascii=False,separators=(',',':'))).replace('__PUBLIC_JSON__',json.dumps(public_data,ensure_ascii=False,separators=(',',':')))
(root/'ui/achievement-prototype.html').write_text(body,encoding='utf-8')
print('Created interactive HTML prototype:',len(body),'characters')
